#pragma once
static const char piko_home_html[] =
"<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PIKO Diagnostics</title>\n"
"<style>body{margin:0;background:#101722;color:#e8effa;font:15px system-ui}header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;background:#1b2636}main{max-width:980px;margin:auto;padding:22px}nav{display:flex;gap:9px;flex-wrap:wrap}a,button{cursor:pointer;border:0;border-radius:9px;background:#293e56;color:white;padding:11px 16px;text-decoration:none;font:inherit}a.active,button.primary{background:#247fba}section{display:none}section.active{display:block}.panel{background:#1b2636;padding:20px;border-radius:12px;margin-top:16px}h1,h2{margin-top:0}.muted{color:#aebed1}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.key{border:1px solid #4d6076;border-radius:11px;padding:16px;background:#101722}.key.on{background:#135e50;border-color:#56d3a8}.key b{font-size:20px;display:block}.key small{color:#b6cce1}input{box-sizing:border-box;width:100%;margin-top:9px;background:#223248;color:white;padding:9px;border:1px solid #60728b;border-radius:7px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:50vh;overflow:auto;background:#0d1420;padding:15px;border-radius:8px}.flex{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.badge{background:#30445b;border-radius:7px;padding:6px 10px}</style>\n"
"<header><strong>PIKO · DCCExpress</strong><span id=\"connection\">Connecting...</span></header><main><nav><a href=\"#home\" data-tab=\"home\">Home</a><a href=\"#diag\" data-tab=\"diag\">Diag</a><a href=\"#console\" data-tab=\"console\">Console</a><a href=\"/keymap\">Key mapper</a><a href=\"/ota\">Firmware update</a></nav>\n"
"<section id=\"home\"><div class=\"panel\"><h1>PIKO Handheld</h1><p class=\"muted\">Hardware discovery dashboard. Select diagnostics to identify physical buttons, or console to review firmware events.</p><div class=\"flex\"><button class=\"primary\" onclick=\"location.hash='diag'\">Open Diag</button><button onclick=\"location.hash='console'\">Open Console</button></div></div></section>\n"
"<section id=\"diag\"><div class=\"panel\"><h2>Raw keypad matrix · 3 × 3</h2><p class=\"muted\">Rows GPIO26 / 14 / 27, columns GPIO32 / 33 / 34. Green means active-low detected. Key identity and active polarity are provisional. Press one physical key at a time.</p><div id=\"matrix\" class=\"grid\"></div><p class=\"muted\">Enter the physical button name or number under each detected cell. Names stay in this browser until exported.</p><div class=\"flex\"><span class=\"badge\" id=\"pressed\">Pressed: none</span><span class=\"badge\" id=\"rotary\">Rotary: —</span><span class=\"badge\" id=\"special\">GPIO12/13: —</span></div><p class=\"muted\" id=\"rawlevels\">Raw columns: loading...</p><div class=\"flex\" style=\"margin-top:14px\"><button class=\"primary\" id=\"copy\">Copy mapping</button><button id=\"reset\">Clear names</button></div><p id=\"feedback\" class=\"muted\"></p></div></section>\n"
"<section id=\"console\"><div class=\"panel\"><h2>Device event console</h2><p class=\"muted\">Recent keypad, STOP and rotary events. This is a diagnostic event log, not a full UART log.</p><div class=\"flex\"><button id=\"copylog\">Copy events</button><button id=\"pause\">Pause</button></div><pre id=\"events\">Loading...</pre></div></section></main>\n"
"<script>\n"
"const rows=[26,14,27],cols=[32,33,34],matrix=document.querySelector('#matrix');\n"
"for(let i=0;i<9;i++){const d=document.createElement('div');d.className='key';d.id='cell'+i;const label='R'+(Math.floor(i/3)+1)+' / C'+(i%3+1);d.innerHTML='<b>'+label+'</b><small>GPIO'+rows[Math.floor(i/3)]+' → GPIO'+cols[i%3]+'</small><input placeholder=\"Physical button (e.g. 1)\" aria-label=\"'+label+' physical key\">';d.querySelector('input').value=localStorage.getItem('piko-key-'+i)||'';d.querySelector('input').oninput=e=>localStorage.setItem('piko-key-'+i,e.target.value);matrix.appendChild(d);}\n"
"function showTab(){const tab=(location.hash||'#home').slice(1);document.querySelectorAll('section').forEach(x=>x.classList.toggle('active',x.id===tab));document.querySelectorAll('a[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));}window.addEventListener('hashchange',showTab);showTab();\n"
"let lastState={},lastEvents=[];\n"
"async function refresh(){try{const [a,b]=await Promise.all([fetch('/api/diag',{cache:'no-store'}),fetch('/api/events',{cache:'no-store'})]);if(!a.ok||!b.ok)throw Error('HTTP error');lastState=await a.json();lastEvents=await b.json();document.querySelector('#connection').textContent='Connected';const active=[];for(let i=0;i<9;i++){const on=(lastState.matrix&(1<<i))!==0;document.querySelector('#cell'+i).classList.toggle('on',on);if(on)active.push('R'+(Math.floor(i/3)+1)+'C'+(i%3+1));}document.querySelector('#pressed').textContent='Pressed: '+(active.join(', ')||'none');document.querySelector('#rotary').textContent='Rotary position: '+lastState.rotary;document.querySelector('#special').textContent='GPIO12: '+lastState.gpio12+' · STOP GPIO13: '+lastState.gpio13;document.querySelector('#rawlevels').textContent='Raw matrix bits: '+lastState.rawMatrix+' · Idle columns: '+lastState.idleColumns+' · Rows: '+(lastState.rowColumns||[]).join(' / ');if(!paused)document.querySelector('#events').textContent=lastEvents.join('\\n')||'No events yet';}catch(e){document.querySelector('#connection').textContent='Disconnected';}}\n"
"let paused=false;document.querySelector('#pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'Resume':'Pause';};\n"
"document.querySelector('#copylog').onclick=()=>navigator.clipboard.writeText(lastEvents.join('\\n'));\n"
"document.querySelector('#copy').onclick=()=>{let lines=['PIKO raw keypad map (GPIO rows 26,14,27; columns 32,33,34)'];for(let i=0;i<9;i++){const v=document.querySelector('#cell'+i+' input').value||'?';lines.push('R'+(Math.floor(i/3)+1)+'C'+(i%3+1)+' GPIO'+rows[Math.floor(i/3)]+'→'+cols[i%3]+' = '+v);}lines.push('Rotary: '+(lastState.rotary??'?'));navigator.clipboard.writeText(lines.join('\\n')).then(()=>document.querySelector('#feedback').textContent='Mapping copied to clipboard.');};\n"
"document.querySelector('#reset').onclick=()=>{if(!confirm('Clear all labels?'))return;for(let i=0;i<9;i++){localStorage.removeItem('piko-key-'+i);document.querySelector('#cell'+i+' input').value='';}};\n"
"setInterval(refresh,350);refresh();\n"
"</script></html>\n";
